  (s.startVerified===true||s.verified===true)&&safeHttps(s.sourceUrl)&&event.timeZone&&
  Number.isFinite(instant(s.startsAt))&&instant(s.startsAt)>=instant(event.startsAt)&&
  instant(s.startsAt)<instant(event.endsAt)&&inVenueZone(s.startsAt,event.timeZone)
