class PanelNode{constructor(){this.hidden=false;this.dataset={};this.attrs={};this.textContent=''}setAttribute(k,v){this.attrs[k]=v}removeAttribute(k){delete this[k]}}
function makePanel(){const p=new PanelNode(),nodes=new Map();p.querySelector=s=>{if(!nodes.has(s))nodes.set(s,new PanelNode());return nodes.get(s)};return p}
for(const width of [320,390,1440])test(`mounted panel mock clock ${width}px: expiry, breaks and rollover without reload`,()=>{
 let clock=at(starts[0])-1000,tick,visible,pageshow;
 const p=makePanel(),root={querySelector:()=>null,addEventListener:(k,fn)=>{visible=fn},removeEventListener:()=>{}},browser={innerWidth:width,setInterval:(fn,ms)=>{assert.equal(ms,1000);tick=fn;return 1},clearInterval:()=>{},addEventListener:(k,fn)=>{pageshow=fn},removeEventListener:()=>{}};
 const stop=mountRacePanels({events:[complete,...data.events.slice(1)]},[p],root,browser,()=>clock);
 assert.equal(p.querySelector('[data-time="seconds"]').textContent,'01');
 for(const [,time,mode] of scenarios){clock=at(time);tick();assert.equal(p.dataset.raceMode,mode);assert.equal(p.hidden,false);assert.equal(p.querySelector('[data-race-watch]').hidden,false);assert.ok(p.querySelector('[data-race-title]').textContent)}
 clock=at('2026-10-24T12:00:00-07:00');visible();assert.equal(p.dataset.raceMode,'live');clock=at('2026-10-24T15:00:00-07:00');pageshow();assert.equal(p.dataset.raceMode,'countdown');stop();
});
